30	// The bundled qemu descriptor (no directory scan, no --describe subprocess).
31	// discover_engines() seeds the registry with it; `run --model fast` resolves
32	// qemu through it directly, paying none of the Verilator-engine discovery cost.
33	EngineDescriptor builtin_qemu();
34	
35	// Select the cycle-accurate engine for `run --model accurate` from an
36	// already-discovered set (pure; spawns nothing). With `want_id` empty, default
37	// to the sole cycle-accurate engine -- erroring if there are none or more than
38	// one (ambiguous). With `want_id` set, that engine must exist and be
39	// cycle-accurate. Returns nullptr and sets `err` (naming the available
40	// cycle-accurate ids) on any failure; the returned pointer aliases into
41	// `engines`, so it must outlive the result.
42	inline const EngineDescriptor* resolve_accurate_engine(
43	    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
44	    std::string& err) {
45	  auto is_accurate = [](const EngineDescriptor& e) {
46	    return e.kind == "cycle-accurate";
47	  };
48	  auto accurate_ids = [&] {
49	    std::vector<std::string> ids;
50	    for (const EngineDescriptor& e : engines)
51	      if (is_accurate(e)) ids.push_back(e.id);
52	    return join(ids, ", ");
53	  };
54	
55	  if (!want_id.empty()) {  // explicit --engine
56	    for (const EngineDescriptor& e : engines) {
57	      if (e.id != want_id) continue;
58	      if (is_accurate(e)) return &e;
59	      err = "engine '" + want_id + "' is " +
60	            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
61	            "; model accurate needs a cycle-accurate engine";
62	      return nullptr;
63	    }
64	    std::string have = accurate_ids();
65	    err = "no engine '" + want_id + "'" +
66	          (have.empty() ? " (no cycle-accurate engines found)"
67	                        : " (cycle-accurate engines: " + have + ")");
68	    return nullptr;
69	  }
70	
71	  // No --engine: default to the sole cycle-accurate engine.
72	  const EngineDescriptor* sole = nullptr;
73	  int n = 0;
74	  for (const EngineDescriptor& e : engines)
75	    if (is_accurate(e)) { sole = &e; ++n; }
76	  if (n == 1) return sole;
77	  if (n == 0)
78	    err = "model accurate: no cycle-accurate engine found "
79	          "(build one with: andes-sim build --what vsim)";
80	  else
81	    err = "model accurate: multiple cycle-accurate engines; select one with "
82	          "--engine (have: " + accurate_ids() + ")";
83	  return nullptr;
84	}
85	
86	}  // namespace andes_sim
87	
88	#endif  // ANDES_SIM_ENGINE_REGISTRY_HPP
