81	// Ask one binary to describe itself: try `<bin> --describe`, else read the
82	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
83	// a human-readable note in `warn`.
84	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
85	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
86	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
87	    json::Parsed p = json::parse(r.out);
88	    if (p.ok) {
89	      std::string err = descriptor_from_json(p.value, d);
90	      if (err.empty()) {
91	        d.bin_path = bin.string();
92	        d.source = "--describe";
93	        return true;
94	      }
95	      warn = bin.string() + ": --describe JSON invalid: " + err;
96	    } else {
97	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
98	    }
99	  }
100	
101	  fs::path sidecar = bin;
102	  sidecar += ".json";
103	  std::error_code ec;
104	  if (fs::exists(sidecar, ec)) {
105	    json::Parsed p = json::parse(read_file(sidecar));
106	    if (p.ok) {
107	      EngineDescriptor sd;
108	      std::string err = descriptor_from_json(p.value, sd);
109	      if (err.empty()) {
110	        sd.bin_path = bin.string();
111	        sd.source = "sidecar";
112	        d = std::move(sd);
113	        return true;
114	      }
115	      warn = sidecar.string() + ": invalid descriptor: " + err;
116	    } else {
117	      warn = sidecar.string() + ": not JSON: " + p.error;
118	    }
119	  }
120	
121	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
122	  return false;
123	}
