62	struct Fixture {
63	  std::string name;
64	  std::string family;
65	};
66	
67	// Extract fixture (name, family) rows from tests/fixtures/Makefile in stable,
68	// family-grouped, file order; dedupe globally; append handoff_roundtrip last.
69	std::vector<Fixture> parse_fixtures(const std::vector<std::string>& lines) {
70	  static const std::pair<std::string, std::string> interesting[] = {
71	      {"RT_FIXTURES", "asm"},
72	      {"RT_C_FIXTURES", "c"},
73	      {"RT_C_V_FIXTURES", "c+rvv"},
74	      {"PROBE_V_FIXTURES", "probe"},
75	  };
76	  std::vector<Fixture> rows;
77	  std::set<std::string> seen;
78	
79	  for (size_t k = 0; k < lines.size(); ++k) {
80	    std::string var, body;
81	    if (!parse_assignment(lines[k], var, body)) continue;
82	    std::string family;
83	    for (const auto& it : interesting)
84	      if (it.first == var) { family = it.second; break; }
85	    if (family.empty()) continue;
86	
87	    // Splice continuation lines: a trailing backslash + newline becomes a space.
88	    size_t li = k;
89	    while (!body.empty() && body.back() == '\\') {
90	      body.pop_back();
91	      body.push_back(' ');
92	      if (++li < lines.size()) body += lines[li];
93	      else break;
94	    }
95	
96	    std::istringstream iss(body);
97	    std::string name;
98	    while (iss >> name)
99	      if (seen.insert(name).second) rows.push_back({name, family});
100	  }
101	
102	  // handoff_roundtrip is not in a *_FIXTURES var; list it explicitly.
103	  if (seen.insert("handoff_roundtrip").second)
104	    rows.push_back({"handoff_roundtrip", "asm"});
105	
106	  return rows;
107	}
