109	int list_fixtures() {
110	  fs::path mk = repo_root() / "tests" / "fixtures" / "Makefile";
111	  bool ok;
112	  std::vector<std::string> lines = read_lines(mk, ok);
113	  if (!ok) {
114	    std::fprintf(stderr, "andes-sim: missing %s\n", mk.c_str());
115	    return 2;
116	  }
117	  std::vector<Fixture> rows = parse_fixtures(lines);
118	
119	  size_t width = 0;
120	  for (const Fixture& r : rows) width = std::max(width, r.name.size());
121	
122	  std::printf("%s  FAMILY\n", ljust("FIXTURE", width).c_str());
123	  for (const Fixture& r : rows)
124	    std::printf("%s  %s\n", ljust(r.name, width).c_str(), r.family.c_str());
125	  return 0;
126	}
