143	int list_engines() {
144	  Discovery disc = discover_engines();
145	
146	  size_t we = 6, wt = 4, wk = 4, wv = 4;  // ENGINE, TYPE, KIND, VLEN headers
147	  for (const EngineDescriptor& e : disc.engines) {
148	    we = std::max(we, e.id.size());
149	    wt = std::max(wt, e.type.size());
150	    wk = std::max(wk, e.kind.size());
151	    wv = std::max(wv, vlen_str(e.vlen).size());
152	  }
153	
154	  std::printf("%s  %s  %s  %s  TRIGGERS\n", ljust("ENGINE", we).c_str(),
155	              ljust("TYPE", wt).c_str(), ljust("KIND", wk).c_str(),
156	              ljust("VLEN", wv).c_str());
157	  for (const EngineDescriptor& e : disc.engines)
158	    std::printf("%s  %s  %s  %s  %s\n", ljust(e.id, we).c_str(),
159	                ljust(e.type, wt).c_str(), ljust(e.kind, wk).c_str(),
160	                ljust(vlen_str(e.vlen), wv).c_str(), join(e.triggers).c_str());
161	
162	  // Binaries that could not self-describe are reported, never silently dropped.
163	  for (const std::string& w : disc.warnings)
164	    std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
165	  return 0;
166	}
