64	// `run --model fast`: QEMU alone, functional, transparent passthrough. Needs
65	// only the built-in qemu descriptor, so it resolves that directly rather than
66	// discover_engines(), which would spawn a --describe subprocess per Verilator
67	// build only to discard them all here.
68	int run_fast(const Cli& cli) {
69	  // fast is QEMU-only; an explicit engine must name it.
70	  if (!cli.engine.empty() && cli.engine != "qemu") {
71	    std::fprintf(stderr,
72	                 "andes-sim run --model fast: engine must be 'qemu', got '%s'\n",
73	                 cli.engine.c_str());
74	    return 2;
75	  }
76	  return run_standalone(cli, builtin_qemu(), "fast");
77	}
