179	// HYBRID_TOOLCHAIN: env first (non-empty wins), else the first matching
180	// assignment in config.env. "" if neither yields a value.
181	std::string read_hybrid_toolchain() {
182	  const char* env = std::getenv("HYBRID_TOOLCHAIN");
183	  if (env && *env) return env;
184	  std::ifstream f(repo_root() / "config.env");
185	  if (!f) return "";
186	  std::string line, val;
187	  while (std::getline(f, line))
188	    if (parse_toolchain_line(line, val)) return val;
189	  return "";
190	}
